/**
 * Local row types for the Recruiter's tables (migration 20261012130000_staff_recruiter.sql).
 * database.types.ts is regenerated by the lead after the Phase 3 merge; until then these are
 * the source of truth and queries use the `Db = any` cast (as sms-agent does).
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Db = any;

export type PayFrequency = "weekly" | "biweekly" | "semimonthly";
export type PayPeriodStatus = "pending" | "awaiting_owner" | "locked" | "unlocked" | "skipped" | "expired" | "empty";

export interface PayPeriodRow {
  id: string;
  organization_id: string;
  company_id: string;
  frequency: PayFrequency;
  start_date: string;
  end_date: string;
  starts_at: string;
  ends_at: string;
  status: PayPeriodStatus;
  approval_id: string | null;
  people: number;
  total_minutes: number;
  ot_minutes: number;
  open_entries: number;
  locked_at: string | null;
  locked_via: string | null;
  locked_by: string | null;
  locked_with_open_entries: boolean;
  unlocked_at: string | null;
  unlocked_by: string | null;
  unlock_reason: string | null;
  csv_emailed_at: string | null;
  csv_emailed_to: string | null;
  csv_email_error: string | null;
  created_at: string;
  updated_at: string;
}

export type PayPeriodAction = "asked" | "locked" | "unlocked" | "csv_emailed" | "csv_downloaded" | "skipped";

export type JobStatus = "draft" | "awaiting_owner" | "open" | "closed" | "rejected" | "expired";

export interface JobPostingRow {
  id: string;
  organization_id: string;
  company_id: string;
  title: string;
  pay_text: string | null;
  employment_type: string | null;
  start_text: string | null;
  location: string | null;
  summary: string | null;
  duties: string[];
  requirements: string[];
  nice_to_have: string[];
  custom_questions: string[];
  owner_request: string | null;
  status: JobStatus;
  draft_source: "ai" | "template";
  approval_id: string | null;
  published_at: string | null;
  owner_texted_at: string | null;
  closed_at: string | null;
  created_at: string;
  updated_at: string;
}

export type ApplicantStatus = "new" | "invited" | "interviewing" | "hired" | "declined" | "withdrawn";

export interface ApplicantAnswer {
  question: string;
  answer: string;
}

export interface JobApplicantRow {
  id: string;
  organization_id: string;
  company_id: string;
  job_id: string;
  contact_id: string | null;
  name: string;
  phone: string;
  email: string | null;
  experience: string | null;
  availability: string | null;
  drivers_licence: boolean | null;
  has_vehicle: boolean | null;
  answers: ApplicantAnswer[];
  status: ApplicantStatus;
  score: number | null;
  score_reason: string | null;
  screening: Record<string, unknown> | null;
  screening_source: "ai" | "rules" | null;
  screened_at: string | null;
  screen_attempts: number;
  confirmation_status: "pending" | "sending" | "sent" | "skipped" | "failed";
  confirmation_sent_at: string | null;
  digest_at: string | null;
  invite_approval_id: string | null;
  invited_at: string | null;
  applied_count: number;
  last_applied_at: string;
  created_at: string;
  updated_at: string;
}

/** The columns of time_entries the payroll reads. */
export interface PayrollEntry {
  id: string;
  company_id: string | null;
  booking_id: string | null;
  profile_id: string;
  started_at: string;
  ended_at: string | null;
  break_minutes: number;
  created_at: string;
  updated_at: string;
}
